/**
 * API Service for Smart Plant Watering System Web App
 * Uses environment variables for backend URL configuration
 */

// Get API URL from environment or use default
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

console.log(`[API] Environment: ${process.env.REACT_APP_ENV || 'development'}`);
console.log(`[API] Connecting to: ${API_BASE_URL}`);

/**
 * Custom API Error class
 */
class APIError extends Error {
  constructor(message, status = 0, data = null) {
    super(message);
    this.name = 'APIError';
    this.status = status;
    this.data = data;
  }
}

/**
 * Helper function to make API requests with authentication token
 */
const fetchWithToken = async (endpoint, options = {}) => {
  try {
    const token = localStorage.getItem('auth_token');

    const headers = {
      'Content-Type': 'application/json',
      ...options.headers,
    };

    if (token) {
      headers.Authorization = `Token ${token}`;
    }

    let response;
    try {
      response = await fetch(`${API_BASE_URL}${endpoint}`, {
        ...options,
        headers,
      });
    } catch (networkError) {
      console.error(`[API] Network error on ${endpoint}:`, networkError);
      throw new APIError(
        'Network request failed. Please check your connection.',
        0,
        { error: networkError.message }
      );
    }

    if (!response.ok) {
      let data;
      try {
        data = await response.json();
      } catch (e) {
        throw new APIError(
          'Server error - invalid response',
          response.status,
          { error: e.message }
        );
      }
      throw new APIError(
        data.detail || data.message || 'An error occurred',
        response.status,
        data
      );
    }

    // Handle 204 No Content
    if (response.status === 204) {
      return { success: true };
    }

    let data;
    try {
      data = await response.json();
    } catch (e) {
      throw new APIError(
        'Invalid response from server',
        response.status,
        { error: e.message }
      );
    }

    return data;
  } catch (error) {
    console.error(`[API] Error on ${endpoint}:`, error);
    throw error;
  }
};

/**
 * Authentication API endpoints
 */
const authAPI = {
  /**
   * Register a new user
   */
  register: async (username, email, password) => {
    try {
      const cleanUsername = username.trim();

      const response = await fetch(`${API_BASE_URL}/users/register/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          username: cleanUsername,
          email,
          password,
          password_confirm: password,
        }),
      });

      let data;
      try {
        data = await response.json();
      } catch (e) {
        throw new APIError(
          'Invalid response from server',
          response.status,
          { error: e.message }
        );
      }

      if (!response.ok) {
        throw new APIError(
          data.detail || data.message || 'Registration failed',
          response.status,
          data
        );
      }

      return data;
    } catch (networkError) {
      console.error('Registration network error:', networkError);
      throw new APIError(
        'Network request failed. Check server status.',
        0,
        { error: networkError.message }
      );
    }
  },

  /**
   * Register an admin user (only if no superusers exist)
   */
  registerAdmin: async (username, email, password, token = null) => {
    try {
      const headers = { 'Content-Type': 'application/json' };
      if (token) {
        headers.Authorization = `Token ${token}`;
      }

      const response = await fetch(`${API_BASE_URL}/users/register_admin/`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          username,
          email,
          password,
          password_confirm: password,
        }),
      });

      let data;
      try {
        data = await response.json();
      } catch (e) {
        throw new APIError(
          'Invalid response from server',
          response.status,
          { error: e.message }
        );
      }

      if (!response.ok) {
        throw new APIError(
          data.detail || data.message || data.error || 'Admin registration failed',
          response.status,
          data
        );
      }

      return data;
    } catch (networkError) {
      console.error('Admin registration network error:', networkError);
      throw new APIError(
        'Network request failed. Check server status.',
        0,
        { error: networkError.message }
      );
    }
  },

  /**
   * Login user and get token
   */
  login: async (username, password) => {
    try {
      const cleanUsername = username.trim();

      console.log(`[AUTH] Attempting login for user: ${cleanUsername}`);
      console.log(`[AUTH] Login endpoint: ${API_BASE_URL}/users/login/`);

      const response = await fetch(`${API_BASE_URL}/users/login/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: cleanUsername, password }),
      });

      console.log(`[AUTH] Response status: ${response.status}`);

      let data;
      try {
        data = await response.json();
        console.log(`[AUTH] Response data:`, data);
      } catch (e) {
        console.error('[AUTH] JSON parse error:', e);
        throw new APIError(
          'Invalid response from server',
          response.status,
          { error: e.message }
        );
      }

      if (!response.ok) {
        const errorMsg = data.detail || data.message || data.non_field_errors?.[0] || 'Login failed';
        console.error(`[AUTH] Login failed: ${errorMsg}`, data);
        throw new APIError(errorMsg, response.status, data);
      }

      console.log('[AUTH] Login successful, token:', data.token?.substring(0, 10) + '...');
      return data;
    } catch (error) {
      console.error('[AUTH] Login error:', error);
      if (error.message?.includes('Network')) {
        throw new APIError(
          'Cannot connect to server. Make sure Django is running on http://localhost:8000',
          0,
          { error: error.message }
        );
      }
      throw error;
    }
  },

  /**
   * Get current user profile
   */
  getCurrentUser: () => fetchWithToken('/users/me/'),

  /**
   * Logout and delete token
   */
  logout: () => fetchWithToken('/users/logout/', { method: 'POST' }),

  /**
   * Update user profile
   */
  updateProfile: (data) => fetchWithToken('/users/update_profile/', {
    method: 'PUT',
    body: JSON.stringify(data),
  }),

  /**
   * Change user password
   */
  changePassword: (oldPassword, newPassword) => fetchWithToken('/users/change_password/', {
    method: 'POST',
    body: JSON.stringify({ old_password: oldPassword, new_password: newPassword }),
  }),

  /**
   * Request password reset
   */
  requestPasswordReset: (email) => fetch(`${API_BASE_URL}/users/request_password_reset/`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email }),
  }).then(async (r) => {
    const data = await r.json();
    if (!r.ok) {
      throw new APIError(
        data.detail || data.message || 'Request failed',
        r.status,
        data
      );
    }
    return data;
  }),
};

/**
 * Plants API endpoints
 */
const plantsAPI = {
  /**
   * Get all user plants
   */
  getAll: () => fetchWithToken('/plants/'),

  /**
   * Get a specific plant
   */
  getById: (plantId) => fetchWithToken(`/plants/${plantId}/`),

  /**
   * Create a new plant
   */
  create: (data) => fetchWithToken('/plants/', {
    method: 'POST',
    body: JSON.stringify(data),
  }),

  /**
   * Update a plant
   */
  update: (plantId, data) => fetchWithToken(`/plants/${plantId}/`, {
    method: 'PUT',
    body: JSON.stringify(data),
  }),

  /**
   * Delete a plant
   */
  delete: (plantId) => fetchWithToken(`/plants/${plantId}/`, {
    method: 'DELETE',
  }),

  /**
   * Water a plant
   */
  water: (plantId) => fetchWithToken(`/plants/${plantId}/water/`, {
    method: 'POST',
  }),
};

/**
 * Watering History API endpoints
 */
const historyAPI = {
  /**
   * Get all watering history for a plant
   */
  getByPlantId: (plantId) => fetchWithToken(`/plants/${plantId}/watering_history/`),

  /**
   * Get system-wide watering history (paginated)
   */
  getAllPaginated: (page = 1, pageSize = 20) => fetchWithToken(`/watering_history/?page=${page}&page_size=${pageSize}`),

  /**
   * Get watering statistics
   */
  getStats: () => fetchWithToken('/watering_history/stats/'),
};

/**
 * Admin API endpoints
 */
const adminAPI = {
  /**
   * Get all users (admin only)
   */
  getAllUsers: () => fetchWithToken('/users/'),

  /**
   * Get user by ID (admin only)
   */
  getUserById: (userId) => fetchWithToken(`/users/${userId}/`),

  /**
   * Get all plants (admin only)
   */
  getAllPlants: () => fetchWithToken('/plants/'),

  /**
   * Delete user (admin only)
   */
  deleteUser: (userId) => fetchWithToken(`/users/${userId}/`, {
    method: 'DELETE',
  }),

  /**
   * Reset user password (admin only)
   */
  resetUserPassword: (userId, newPassword) => fetchWithToken(`/users/${userId}/reset_password/`, {
    method: 'POST',
    body: JSON.stringify({
      user_id: userId,
      new_password: newPassword,
    }),
  }),

  /**
   * Get system-wide admin statistics (all plants, all users)
   */
  getAdminStats: () =>
    fetchWithToken('/plants/admin_stats/'),
};

const apiService = {
  authAPI,
  plantsAPI,
  historyAPI,
  adminAPI,
};

export default apiService;

